switch (tipoCarga) {
case FRAGIL -> tarifa = tarifa.add(BigDecimal.valueOf(15));
case PERECIVEL -> tarifa = tarifa.add(BigDecimal.valueOf(25));
}
if (clienteFidelidade)
tarifa = tarifa.multiply(BigDecimal.valueOf(0.9));
return tarifa.setScale(2, RoundingMode.HALF_UP);
