BigDecimal subtotalComCategoria =
subtotalDiarias.multiply(BigDecimal.valueOf(categoria.getFatorMultiplicador()));
// 4. Taxa fixa de higienização
BigDecimal totalComHigienizacao =
subtotalComCategoria.add(categoria.getTaxaLimpeza());
// 5. Desconto de convênio
BigDecimal totalFinal = possuiConvenio
? totalComHigienizacao.multiply(FATOR_DESCONTO_CONVENIO)
: totalComHigienizacao;
